@IsTest private class AuditClockProbe62 {
@IsTest static void sequential(){
Set<Id> ids=new Set<Id>();
for(Integer i=0;i<4;i++){Account a=new Account(Name='Owned audit '+i);insert a;ids.add(a.Id);}
Datetime cutoff=System.now().addHours(0);Datetime earlier=cutoff.addHours(-1);
Map<String,Object> observation=new Map<String,Object>{
'createdByCutoff'=>[SELECT COUNT() FROM Account WHERE Id IN :ids AND CreatedDate<=:cutoff],
'modifiedByCutoff'=>[SELECT COUNT() FROM Account WHERE Id IN :ids AND LastModifiedDate<=:cutoff],
'olderThreshold'=>[SELECT COUNT() FROM Account WHERE Id IN :ids AND CreatedDate<=:earlier]};
System.assertEquals('AUDIT_CUTOFF_OBSERVATION',JSON.serialize(observation),'AUDIT_CUTOFF_OBSERVATION');
}
@IsTest static void batch(){
Account one=new Account(Name='Owned first');insert one;Account two=new Account(Name='Owned second');insert two;
Set<Id> ids=new Set<Id>{one.Id,two.Id};Test.startTest();Database.executeBatch(new AuditCutoffBatch62(ids),200);Test.stopTest();
Map<String,Object> observation=new Map<String,Object>{'remainingAfterBatch'=>[SELECT COUNT() FROM Account WHERE Id IN :ids]};
System.assertEquals('AUDIT_CUTOFF_OBSERVATION',JSON.serialize(observation),'AUDIT_CUTOFF_OBSERVATION');
}
@IsTest static void future(){
Account a=new Account(Name='Owned future audit');insert a;Id key=a.Id;
Datetime future=System.now().addDays(1);Test.setCreatedDate(key,future);Datetime cutoff=System.now();
Datetime stored=[SELECT CreatedDate FROM Account WHERE Id=:key].CreatedDate;
Map<String,Object> observation=new Map<String,Object>{'futureByCutoff'=>[SELECT COUNT() FROM Account WHERE Id=:key AND CreatedDate<=:cutoff],'clockBeforeFuture'=>cutoff<future,'futureStillStored'=>stored>cutoff};
System.assertEquals('AUDIT_CUTOFF_OBSERVATION',JSON.serialize(observation),'AUDIT_CUTOFF_OBSERVATION');
}
}

